  flex-direction: column;
  width: 236px;
  padding: 27px 17px 0;
  background: #f7f8fb;
  border-right: 1px solid #e9ebf1;
  overflow-y: auto;
  overscroll-behavior: contain;
}
.workspace-sidebar > *,
.mobile-sidebar > * {
  flex-shrink: 0;
}
.mobile-sidebar {
  width: min(300px, calc(100vw - 24px));
  max-width: 300px;
  height: 100dvh;
  padding: max(24px, env(safe-area-inset-top)) 16px
    max(0px, env(safe-area-inset-bottom));
