  align-items: center;
  justify-content: center;
  margin-left: auto;
  width: 44px;
  height: 44px;
}
.mobile-sidebar
  :is(
    .nav-caption,
    .sidebar-search,
    .workspace-switcher small,
    .sidebar-team small,
    .sidebar-note p
  ) {
  color: #697588;
}
.brand {
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 0 13px 25px;
  font-size: 23px;
  font-weight: 750;
  letter-spacing: -1.2px;
}
.brand-dash {
  color: #9ba0b3;
  padding: 0 1px;
  font-weight: 400;
}
.brand-icon {
  display: grid;
  grid-template-columns: 9px 9px;
  gap: 3px;
  width: 22px;
  transform: rotate(-8deg);
}
.brand-icon span {
  height: 9px;
  border-radius: 2.5px;
  background: #7774d8;
}
.brand-icon span:first-child {
  grid-row: span 2;
  height: 21px;
  background: #5556b4;
}
.brand-icon span:last-child {
  background: #b0adeb;
}
.workspace-switcher {
  display: flex;
  gap: 10px;
  align-items: center;
  width: 100%;
  text-align: left;
  padding: 11px 10px;
  background: #fff;
  border: 1px solid #e6e8ef;
  border-radius: 9px;
  margin-bottom: 16px;
}
.workspace-switcher > span:nth-child(2) {
  flex: 1;
  min-width: 0;
}
.workspace-switcher strong,
.workspace-switcher small {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.workspace-switcher strong {
  font-size: 12px;
  font-weight: 650;
}
.workspace-switcher small {
  color: #858c9b;
  font-size: 11px;
  margin-top: 2px;
}
.workspace-letter {
  display: grid;
  place-items: center;
  width: 31px;
  height: 31px;
  border-radius: 7px;
  background: #edecfa;
  color: #6662bd;
  font-weight: 700;
}
.sidebar-search {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 7px 11px;
  color: #9298a7;
  font-size: 12px;
  width: 100%;
  text-align: left;
  margin-bottom: 20px;
}
.sidebar-search span {
  flex: 1;
}
.sidebar-search kbd {
  border: 1px solid #e2e4ec;
  border-radius: 4px;
  padding: 1px 4px;
  font-size: 10px;
}
.nav-caption {
  font-size: 9px;
  font-weight: 650;
  letter-spacing: 1.3px;
  color: #9ba1ae;
  padding: 0 13px;
  margin-bottom: 9px;
}
.nav-caption-second {
  margin-top: 25px;
}
.nav-item {
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 10px 12px;
  border-radius: 7px;
