}
.nav-count {
  font-size: 10px;
  color: #878b9f;
  border-radius: 4px;
  background: #edf0f5;
  padding: 0 5px;
}
.nav-active .nav-count {
  color: #6a66bf;
  background: #dfdef4;
}
.nav-spark {
  color: #a39bdc;
}
.sidebar-note {
  margin: 26px 4px 20px;
  padding: 14px;
  text-align: left;
  border: 1px solid #e4e2f5;
  border-radius: 10px;
  background: #f2f1fc;
}
.note-mini-icon {
  display: grid;
  place-items: center;
  width: 29px;
  height: 29px;
  border-radius: 7px;
  background: #e6e3f7;
