  margin-bottom: 9px;
}
.sidebar-note strong {
  display: block;
  font-size: 11.5px;
  color: #5f5a80;
}
.sidebar-note p {
  margin: 5px 0 12px;
  color: #9590aa;
  font-size: 10.5px;
  line-height: 1.7;
}
.sidebar-note > span:last-child {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 10.5px;
  color: #7770b7;
}
.sidebar-bottom {
  margin-top: auto;
