}
.sidebar-team {
  display: flex;
  gap: 12px;
  align-items: center;
  border-top: 1px solid #e6e8ef;
  margin-top: 15px;
  padding: 19px 6px;
  font-size: 10px;
  color: #616a7b;
}
.sidebar-team small {
  color: #9a9faf;
  font-size: 9px;
}
.avatar-stack {
  display: flex;
  padding-left: 6px;
}
.avatar-stack > * {
  margin-left: -6px;
  border: 2px solid #f7f8fb;
}
.person-avatar {
  display: inline-flex;
