  justify-content: center;
  flex-shrink: 0;
  height: 33px;
  width: 33px;
  border-radius: 50%;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: -0.3px;
}
.person-avatar-sm {
  height: 25px;
  width: 25px;
  font-size: 9px;
}
.avatar-0 {
  background: #e9e6fa;
  color: #7a70b4;
}
.avatar-1 {
  background: #fce8df;
  color: #b98665;
}
.avatar-2 {
  background: #ddefe9;
  color: #5a9785;
}
.avatar-3 {
  background: #e2edfb;
  color: #6488b2;
}
.avatar-4 {
  background: #f5e2ed;
  color: #ac79a0;
}
.avatar-5 {
  background: #f3ebd8;
  color: #a68c56;
}
.workspace-shell {
  margin-left: 236px;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}
.workspace-topbar {
  height: 68px;
  padding: 0 35px;
  border-bottom: 1px solid #e9ebf1;
  background: #fff;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}
.breadcrumbs,
.topbar-actions {
