}
.connection-offline {
  color: #c07e56;
}
.workspace-main {
  width: 100%;
  max-width: 1540px;
  padding: 32px 36px 38px;
  margin: 0 auto;
  flex: 1;
}
.workspace-footer {
  display: flex;
  justify-content: space-between;
  gap: 15px;
  padding: 18px 36px;
  font-size: 10px;
  color: #a6acb9;
