  font-weight: 550;
}
.welcome-banner {
  position: relative;
  display: flex;
  align-items: center;
  gap: 25px;
  padding: 28px 30px;
  border-radius: 13px;
  background: #f0effb;
  border: 1px solid #e8e5f7;
  margin-bottom: 24px;
  overflow: hidden;
}
.welcome-copy {
  flex: 1;
}
.welcome-copy .small-label {
  color: #938ac0;
}
.welcome-copy h2 {
  font-size: 23px;
  letter-spacing: -0.7px;
  line-height: 1.35;
  font-weight: 600;
  color: #49476a;
  margin: 6px 0 8px;
}
.welcome-copy p {
  color: #9290aa;
  font-size: 11px;
  max-width: 375px;
  line-height: 1.8;
}
.welcome-actions {
  display: flex;
  flex-direction: column;
  gap: 7px;
}
.welcome-actions button {
  font-size: 11px;
}
.welcome-art {
  position: relative;
  height: 110px;
  width: 134px;
  flex-shrink: 0;
}
.art-card {
  position: absolute;
  border: 1px solid #dfd9ee;
  border-radius: 9px;
  background: #fff;
  width: 105px;
  height: 67px;
  box-shadow: 0 7px 17px #6c578512;
}
.art-back {
  top: 8px;
  left: 3px;
  transform: rotate(-12deg);
  background: #f9f6ff;
  padding: 17px;
}
.art-card span:not(.art-check) {
  display: block;
  height: 4px;
  background: #ded9ed;
  width: 43px;
  margin: 6px 0;
  border-radius: 3px;
}
.art-card span:not(.art-check):last-child {
  width: 28px;
}
.art-front {
  left: 20px;
  top: 36px;
  transform: rotate(7deg);
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 9px;
}
.art-check {
  display: grid;
  place-items: center;
  width: 26px;
  height: 26px;
  color: #8f87c2;
  background: #eae7f9;
  border-radius: 7px;
}
.art-spark {
  position: absolute;
  right: 2px;
  top: 0;
  color: #ae9bd9;
}
.metrics-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 16px;
  margin-bottom: 26px;
}
.metric-card {
  background: #fff;
  border: 1px solid #e9ebf1;
  padding: 18px 20px;
  border-radius: 10px;
}
.metric-label {
  display: flex;
  align-items: center;
  justify-content: space-between;
  color: #8890a1;
  font-size: 11px;
  gap: 8px;
}
.metric-icon {
  display: grid;
  place-items: center;
  width: 29px;
  height: 29px;
  border-radius: 8px;
}
.purple,
.lavender {
  background: #eeebfb;
  color: #9990ce;
}
.blue {
  background: #eaf1fb;
  color: #7b9cc9;
}
.amber,
.peach {
  background: #fff1df;
  color: #c8a071;
}
.mint {
  background: #e6f2ec;
  color: #80a694;
}
.metric-number {
  margin: 8px 0 6px;
  font-size: 27px;
  line-height: 1.2;
  color: #42495b;
  letter-spacing: -0.8px;
  font-weight: 600;
}
.metric-card p {
  color: #a1a6b3;
  font-size: 9.5px;
  margin: 0;
}
.overview-columns {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 285px;
  gap: 23px;
  align-items: start;
}
.overview-main,
.overview-aside {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 23px;
}
.workspace-card {
  padding: 21px 23px;
  background: #fff;
  border: 1px solid #e9ebf1;
  border-radius: 11px;
  min-width: 0;
}
.section-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 20px;
}
.section-heading h2 {
  display: flex;
  align-items: center;
  gap: 9px;
  font-size: 12.5px;
  font-weight: 600;
  margin: 0;
  color: #52596a;
}
.section-heading h2 [data-slot="badge"] {
  font-size: 10px;
  border-radius: 5px;
  padding: 0 5px;
  color: #9298a7;
}
.section-heading button {
  font-size: 10px;
  color: #999cac;
  height: auto;
  padding: 2px 0 2px 6px;
}
.journey {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  row-gap: 19px;
  padding: 6px 0 24px;
}
.journey-step {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  gap: 9px;
  padding: 0 6px;
  color: #a5aaba;
  font-size: 9px;
  line-height: 1.5;
}
.journey-step::before {
  content: "";
  position: absolute;
  top: 13px;
  right: 50%;
  width: 100%;
  height: 1px;
  background: #eeedf5;
}
.journey-step:nth-child(4n + 1)::before {
  display: none;
}
.step-number {
  display: grid;
  place-items: center;
  width: 27px;
  height: 27px;
  border-radius: 50%;
  border: 1px solid #e8e7ef;
  background: #fafaff;
  position: relative;
  z-index: 1;
  font-size: 10px;
}
.step-current {
  color: #7771b5;
}
.step-current .step-number {
  background: #ece9fb;
  border-color: #cdc7eb;
  color: #756bb8;
  box-shadow: 0 0 0 4px #f6f4fd;
}
.step-done .step-number {
  background: #e6f2ec;
  border-color: #d9eae1;
  color: #6b9b84;
}
.step-done {
  color: #7fa491;
}
.journey-footer {
  display: flex;
  align-items: center;
  gap: 15px;
  justify-content: space-between;
  padding-top: 15px;
  border-top: 1px solid #f0f1f6;
}
.journey-footer p {
  color: #888e9e;
  font-size: 10px;
  line-height: 1.65;
  margin: 4px 0 0;
  max-width: 350px;
}
.journey-footer button {
  flex-shrink: 0;
  font-size: 10px;
  color: #7c7a9c;
}
.next-task {
  display: flex;
  align-items: center;
  gap: 11px;
  width: 100%;
  text-align: left;
  padding: 14px 0;
  border-bottom: 1px solid #f1f2f6;
  color: #a5a8b9;
}
.next-task:last-child {
  border-bottom: none;
}
.next-task > div {
  flex: 1;
  min-width: 0;
}
.next-task strong {
  display: block;
  color: #666c7b;
  font-size: 11.5px;
  font-weight: 500;
  overflow-wrap: anywhere;
}
.next-task > div > span {
  color: #a6aabb;
  font-size: 9px;
  margin-top: 5px;
  display: block;
}
.status-badge {
  display: inline-flex;
  align-items: center;
  white-space: nowrap;
  gap: 5px;
  padding: 3px 7px;
  border-radius: 5px;
  font-size: 9px;
  line-height: 1.4;
  background: #f3f4f7;
  color: #949cad;
}
.status-building {
  background: #eeeafa;
  color: #9a88cb;
}
.status-integrating {
  background: #fff0da;
  color: #c5a16a;
}
.status-demo-ready {
  background: #e9f4ed;
  color: #80a68e;
}
.document-shortcuts {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 11px;
}
.document-shortcuts button {
  position: relative;
  padding: 15px 13px;
  text-align: left;
  border: 1px solid #eeeff4;
  border-radius: 8px;
  background: #fdfdff;
}
.document-shortcuts button > svg {
  position: absolute;
  right: 11px;
  top: 13px;
  color: #bdc0cc;
}
.document-shortcuts strong {
  font-size: 11px;
  color: #73788a;
  display: block;
  margin: 12px 0 5px;
  font-weight: 550;
}
.document-shortcuts button > span:last-of-type {
  font-size: 8.5px;
  color: #a5a9b7;
  display: block;
}
.document-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 37px;
  height: 40px;
  border-radius: 8px;
  flex-shrink: 0;
}
.activity-list {
  display: flex;
  flex-direction: column;
  gap: 17px;
}
.activity-item {
  display: flex;
  gap: 10px;
  align-items: flex-start;
}
.activity-item > div {
  min-width: 0;
}
.activity-item p {
  margin: 0;
  line-height: 1.7;
  font-size: 10px;
}
.activity-item strong {
  font-weight: 550;
  color: #73798b;
  margin-right: 7px;
}
.activity-item p span {
  color: #979dae;
  overflow-wrap: anywhere;
}
.activity-item small {
  font-size: 9px;
  color: #b1b5c1;
}
.section-footnote {
  margin: 15px 0 0;
  color: #a2a8b7;
  font-size: 9px;
  line-height: 1.7;
}
.deadline-card {
  background: #f5f3fc;
  border: 1px solid #e9e4f6;
  border-radius: 11px;
  padding: 21px;
}
.deadline-label {
  display: flex;
  align-items: center;
  gap: 8px;
  color: #a49bbf;
  font-size: 11px;
}
.time-units {
  display: flex;
  align-items: center;
  gap: 25px;
  margin: 22px 0;
}
.time-units > div {
  position: relative;
  text-align: center;
}
.time-units strong {
  font-size: 29px;
  font-weight: 550;
  color: #766990;
  letter-spacing: -1px;
}
.time-units span {
  font-size: 9px;
  color: #b0a7c2;
  display: block;
  margin-top: 3px;
}
.time-units > div:not(:last-child)::after {
  content: ":";
  position: absolute;
  right: -15px;
  top: 4px;
  color: #cbc4d9;
  font-size: 21px;
