.no-deadline {
  margin: 24px 0 20px;
}
.no-deadline > svg {
  color: #b7accd;
  margin-bottom: 12px;
}
.no-deadline h3 {
  font-weight: 550;
  font-size: 14px;
  color: #7d718f;
  letter-spacing: -0.2px;
}
.no-deadline p {
  font-size: 10px;
  line-height: 1.8;
  color: #ada3b9;
  margin-top: 7px;
}
.deadline-details {
  display: flex;
  flex-direction: column;
  margin-top: 14px;
  gap: 3px;
}
.deadline-details > span {
  color: #b2a9c2;
  font-size: 9px;
}
.deadline-details strong {
  color: #a296b4;
  font-weight: 450;
  font-size: 10px;
}
.deadline-edit {
  border-top: 1px solid #e9e3f3;
  margin-top: 17px;
  padding-top: 12px;
  display: flex;
  align-items: center;
  gap: 6px;
  color: #a598b9;
  font-size: 9.5px;
  width: 100%;
}
.progress-ring {
  width: 134px;
  height: 134px;
  position: relative;
  margin: 8px auto 19px;
}
.progress-ring svg {
  width: 100%;
  height: 100%;
  transform: rotate(-90deg);
}
.progress-ring circle {
  fill: none;
  stroke-width: 8;
}
.ring-track {
  stroke: #efedf8;
}
.ring-fill {
  stroke: #b5a8da;
  stroke-linecap: round;
  transition: stroke-dasharray 0.3s;
}
.progress-ring > div {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
}
.progress-ring strong {
  font-size: 26px;
  font-weight: 550;
  color: #9f95bb;
}
.progress-ring span {
  font-size: 9px;
  color: #b7b3c4;
  margin-top: 4px;
