  justify-content: center;
  align-items: center;
  gap: 5px;
  color: #aba7b9;
  font-size: 8.5px;
}
.readiness.verified {
  color: #80a691;
}
.milestone-progress {
  display: flex;
  flex-direction: column;
  gap: 13px;
